let observations=[],pending=[],demoMode=false,activeModel=null;
try{const data=JSON.parse(localStorage.getItem('worth-learning-v1')||'{}');observations=Array.isArray(data.observations)?data.observations.filter(MomentaryModel.valid):[];pending=Array.isArray(data.pending)?data.pending.filter(e=>e&&typeof e.scale==='string'&&['certain','uncertain'].includes(e.kind)&&Number.isFinite(e.expected)&&e.expected>=0&&e.expected<=10):[]}catch{}
function learningProfile(){const p=getPersonalProfile();return p.scaleDefinition&&p.anchorLow&&p.anchorMid&&p.anchorHigh?{key:JSON.stringify([p.scaleDefinition,p.anchorLow,p.anchorMid,p.anchorHigh]),p}:null}
function storeLearning(nextObservations,nextPending){try{localStorage.setItem('worth-learning-v1',JSON.stringify({observations:nextObservations,pending:nextPending}));observations=nextObservations;pending=nextPending;return true}catch{put('learningMessage','Browser storage is unavailable. The observation was not saved.');return false}}
function relevantEvents(){const profile=learningProfile();return demoMode?MomentaryModel.demo():profile?observations.filter(e=>e.scale===profile.key):[]}
function renderLearning(){const profile=learningProfile();put('learningScale',profile?'Using your current scale: '+profile.p.scaleDefinition+'. A changed definition or anchor starts a separate history.':'Define happiness and all three anchors above before recording personal observations.');$('recordExpectation').disabled=!profile||demoMode;$('modelReal').hidden=!demoMode;put('modelBanner',demoMode?'SIMULATED DEMONSTRATION — generated outcomes, not your data or evidence about you.':'Your observations stay on this device. No trained data is shared with GitHub or Sites.');const data=relevantEvents();activeModel=MomentaryModel.train(data);const box=$('modelEvidence');box.replaceChildren();addText(box,'p',`${activeModel.n} observation${activeModel.n===1?'':'s'} · ${demoMode?'simulated':'your current scale'}`,'metric-line');if(activeModel.mae!==undefined){addText(box,'p',`Held-out average error: ${activeModel.mae.toFixed(2)} happiness points. Baseline error: ${activeModel.baselineMae.toFixed(2)} points.`,'metric-line');addText(box,'p',`${activeModel.trainN} training observations; ${activeModel.testN} later test observations. Selected memory factor γ = ${activeModel.gamma}.`,'helper')}addText(box,'p',activeModel.reason,'helper');if(activeModel.ready)addText(box,'p','The model can calculate next-event scenarios. Its average test error is not a confidence interval.','helper');if(activeModel.beta){const params=addText(box,'details','');addText(params,'summary','Fitted coefficients');addText(params,'p',activeModel.beta.map((v,i)=>'w'+i+' = '+v.toFixed(3)).join(' · '),'helper')}renderPending();const history=$('learningHistory');history.replaceChildren();data.slice(-20).reverse().forEach(e=>addText(history,'p',`${e.label||'Event'} · ${e.kind} · expected ${e.expected}/10 · reward ${e.reward}/10 · happiness ${e.happiness.toFixed(1)}/10`,'helper'));if(!data.length)addText(history,'p','No completed observations on this scale yet.','helper');$('learnedPrediction').replaceChildren();}
function renderPending(){const box=$('pendingEvents');box.replaceChildren();if(demoMode){addText(box,'p','Exit the simulation to record real outcomes.','helper');return}const profile=learningProfile();const list=profile?pending.filter(e=>e.scale===profile.key):[];if(!list.length){addText(box,'p','Your recorded expectations will appear here for follow-up.','helper');return}list.forEach(e=>{const form=document.createElement('form');form.className='option';addText(form,'strong',e.label);addText(form,'p',`Expected reward: ${e.expected}/10 · recorded ${new Date(e.startedAt).toLocaleString()}`,'helper');const reward=document.createElement('input');reward.type='number';reward.min=0;reward.max=10;reward.step=.5;reward.required=true;reward.setAttribute('aria-label','Actual reward for '+e.label);const rlabel=document.createElement('label');rlabel.textContent='Actual reward · 0–10';if(e.kind==='certain'){reward.value=e.expected;reward.readOnly=true;rlabel.textContent='Known reward · fixed from your prior entry'}form.append(rlabel,reward);const happiness=document.createElement('input');happiness.type='number';happiness.min=0;happiness.max=10;happiness.step=.5;happiness.required=true;happiness.setAttribute('aria-label','Happiness after '+e.label);addText(form,'label','How happy do you feel right now · your 0–10 scale?');form.append(happiness);const button=document.createElement('button');button.type='submit';button.className='quiet';button.textContent='Record outcome';form.append(button);form.onsubmit=event=>{event.preventDefault();if(!form.checkValidity())return;const observation={...e,reward:Number(reward.value),happiness:Number(happiness.value),completedAt:new Date().toISOString()};if(storeLearning([...observations,observation],pending.filter(p=>p.id!==e.id))){put('learningMessage','Outcome saved. The model check has been updated.');renderLearning()}};box.append(form)})}
$('expectationForm').onsubmit=e=>{e.preventDefault();const profile=learningProfile();if(!profile||demoMode)return;const entry={id:crypto.randomUUID(),scale:profile.key,label:$('eventLabel').value.trim(),kind:$('eventKind').value,expected:Number($('eventExpected').value),startedAt:new Date().toISOString()};if(!entry.label)return;if(storeLearning(observations,[...pending,entry])){$('expectationForm').reset();put('learningMessage','Expectation saved. Come back after the event to record the outcome.');renderLearning()}};
$('modelDemo').onclick=()=>{demoMode=true;renderLearning()};$('modelReal').onclick=()=>{demoMode=false;renderLearning()};
function scenarioType(){const certain=$('scenarioKind').value==='certain';['scenarioLow','scenarioHigh'].forEach(id=>{$(id).disabled=certain;$(id).required=!certain})}$('scenarioKind').onchange=scenarioType;
$('modelScenario').onsubmit=e=>{e.preventDefault();const box=$('learnedPrediction');box.replaceChildren();if(!activeModel?.ready){addText(box,'p',activeModel?.reason||'Record observations first.','metric-line');return}const kind=$('scenarioKind').value,expected=Number($('scenarioExpected').value),low=kind==='certain'?expected:Number($('scenarioLow').value),high=kind==='certain'?expected:Number($('scenarioHigh').value);if(low>high||expected<low||expected>high){addText(box,'p','Use a lower reward ≤ expected reward ≤ higher reward.','metric-line');return}const center=MomentaryModel.predict(activeModel,{kind,expected,reward:expected}),a=MomentaryModel.predict(activeModel,{kind,expected,reward:low}),b=MomentaryModel.predict(activeModel,{kind,expected,reward:high});if(!center||!a||!b){addText(box,'p','Your history has no observations of this reward type yet.','metric-line');return}addText(box,'p',demoMode?'Simulated model output':'Experimental learned estimate','eyebrow');addText(box,'p',`${center.value.toFixed(1)} / 10 if the reward matches your expectation.`,'score-number');if(kind==='uncertain')addText(box,'p',`If reward is ${low}/10 → happiness estimate ${a.value.toFixed(1)}/10. If reward is ${high}/10 → ${b.value.toFixed(1)}/10.`);addText(box,'p',`Average held-out error was ${activeModel.mae.toFixed(2)} points across ${activeModel.testN} later observations. This does not establish an error bound for this event.`,'helper');if(center.clipped||a.clipped||b.clipped)addText(box,'p','At least one raw estimate fell outside 0–10 and was clipped. Treat that scenario with particular caution.','helper');if(center.extrapolation||a.extrapolation||b.extrapolation)addText(box,'p','At least one reward is outside the range of your recorded rewards. This is an extrapolation.','helper');addText(box,'p','This uses the next event in your recorded sequence. It does not establish whether choosing this event causes greater happiness than another choice.','helper')};
personalFields.slice(0,4).forEach(id=>$(id).addEventListener('change',renderLearning));$('savePersonal').addEventListener('click',renderLearning);renderLearning();
